```sql
SELECT TP_DEPENDENCIA, COUNT(DISTINCT CO_ENTIDADE) AS escolas, SUM(QT_MAT_BAS) AS matriculas, ROUND(1.0 * SUM(QT_MAT_BAS) / COUNT(DISTINCT CO_ENTIDADE), 1) AS media
FROM matriculas
GROUP BY TP_DEPENDENCIA
ORDER BY media DESC;
```

